-- The core of the task platform's data model (BRIEF.md, "What cannot change", rule 3).
-- Do not edit this file. Add columns, tables and every policy in your own
-- migrations, timestamped after this one.

create table public.tracks (
  id uuid primary key default gen_random_uuid(),
  name text not null unique,
  description text not null default '',
  archived boolean not null default false,
  created_at timestamptz not null default now()
);

create table public.sessions (
  id uuid primary key default gen_random_uuid(),
  track_id uuid not null references public.tracks on delete cascade,
  title text not null,
  held_on date not null,
  created_at timestamptz not null default now()
);
create index sessions_track_id_idx on public.sessions (track_id);

-- Being a Mentor is this row, not a role: an Officer names the person's
-- email, and they become a Mentor of this Session when they sign in with it.
create table public.session_mentors (
  session_id uuid not null references public.sessions on delete cascade,
  email text not null check (email = lower(btrim(email)) and email like '%@%'),
  primary key (session_id, email)
);
create index session_mentors_email_idx on public.session_mentors (email);

create table public.tasks (
  id uuid primary key default gen_random_uuid(),
  session_id uuid not null references public.sessions on delete cascade,
  title text not null,
  instructions text not null,
  grading_criteria text not null,
  deadline timestamptz not null,
  -- What a Submission to this Task may contain: a text answer, a file, or both.
  formats text[] not null default '{text}'
    check (cardinality(formats) > 0 and formats <@ '{text,file}'),
  created_at timestamptz not null default now()
);
create index tasks_session_id_idx on public.tasks (session_id);

-- One attempt by a Learner. Deleting a Member deletes their work with it.
-- Lateness is created_at against tasks.deadline, never stored.
create table public.submissions (
  id uuid primary key default gen_random_uuid(),
  task_id uuid not null references public.tasks on delete cascade,
  member_id uuid not null references public.members on delete cascade,
  body text,
  -- Object path in the `submissions` bucket.
  file_path text,
  created_at timestamptz not null default now(),
  check (body is not null or file_path is not null)
);
create index submissions_task_member_idx on public.submissions (task_id, member_id);

-- The AI's score and feedback on one Submission, and a Mentor's override.
-- The row exists from the moment the Submission is saved, as `pending`.
create table public.evaluations (
  submission_id uuid primary key references public.submissions on delete cascade,
  status text not null default 'pending' check (status in ('pending', 'done', 'failed')),
  ai_score integer check (ai_score between 0 and 100),
  ai_feedback text,
  model text,
  override_score integer check (override_score between 0 and 100),
  override_note text,
  overridden_by text,
  overridden_at timestamptz,
  updated_at timestamptz not null default now(),
  check (status <> 'done' or (ai_score is not null and ai_feedback is not null))
);

-- Deny-all until your policies say otherwise.
alter table public.tracks enable row level security;
alter table public.sessions enable row level security;
alter table public.session_mentors enable row level security;
alter table public.tasks enable row level security;
alter table public.submissions enable row level security;
alter table public.evaluations enable row level security;

-- Private: files are never served publicly. Write your own policies on
-- storage.objects for this bucket. 10 MB is BRIEF.md's limit.
insert into storage.buckets (id, name, public, file_size_limit)
values ('submissions', 'submissions', false, 10485760);
